### Ran Playwright code
```js
await (async (page) => { await page.locator('#software-stop').click(); await page.waitForFunction(()=>document.querySelector('#safety-stop-request').textContent.includes('已送达'),{},{timeout:10000}); const result=await page.evaluate(()=>Object.fromEntries(['safety-stop-request','safety-stop-confirmed','safety-cancel-ack','safety-cancel-final'].map(id=>[id,document.getElementById(id).textContent]))); await page.locator('#pause').click(); return {stop:result,paused:await page.evaluate(()=>({motion:document.querySelector('#motion-physical').textContent, highlights:document.querySelectorAll('.fsm-flow [aria-current=step]').length,confirmed:document.querySelector('#safety-stop-confirmed').textContent}))}; })(page);
```
